/**
 * Build the complete ACC CSV file content and filename from the day's data.
 *
 * @param {string}  shiftKey      YYMMDD format, e.g. "260210"
 * @param {string}  uploadCounter Zero-padded 2-digit string, e.g. "01"
 * @param {object}  mode          ACC mode settings ({ posCode: string })
 * @param {AccDayData} accDayData Built from AccDataBuilder.build()
 * @returns {{ filename: string, content: string }}
 */
function calcDailyFile(shiftKey, uploadCounter, mode, accDayData) {
  const posCode = mode?.posCode ?? 'ACC-POS-0001';
  const salesDate = Moment.tz(shiftKey, 'YYMMDD', 'Asia/Manila').format('MM/DD/YY');
  const mmddyy = Moment.tz(shiftKey, 'YYMMDD', 'Asia/Manila').format('MMDDYY');
  const filename = `${mmddyy}${uploadCounter}.csv`;

  const lines = [CSV_HEADER];
  for (const term of accDayData.terminals) {
    const termNo = term.terminalNumber;
    for (let h = 0; h < 24; h++) {
      const salesTime = String(h).padStart(2, '0') + ':00';
      lines.push(buildLine('01', salesTime, posCode, salesDate, termNo, term.hours[h]));
    }

    lines.push(
      buildLine('99', SUMMARY_SALES_TIME, posCode, salesDate, termNo, term.dailySummary)
    );
  }

  if (accDayData.terminals.length > 0) {
    const grandRow = buildGrandTotalRow(accDayData.terminals);
    const lastTermNo =
      accDayData.terminals[accDayData.terminals.length - 1].terminalNumber;
    lines.push(buildLine('95', SUMMARY_SALES_TIME, posCode, salesDate, lastTermNo, grandRow));
  }

  return {
    filename,
    content: lines.join('\r\n'),
  };
}

/**
 * Sum all terminal daily summaries into one grand-total AccRow for the 95 line.
 *
 * @param {import('./types').TerminalData[]} terminals
 * @returns {AccRow}
 */
function buildGrandTotalRow(terminals) {
  /** @type {AccRow} */
  const grand = /** @type {any} */ ({});

  for (const key of Object.keys(terminals[0].dailySummary)) {
    grand[key] = 0;
  }

  for (const term of terminals) {
    for (const key of Object.keys(grand)) {
      grand[key] += term.dailySummary[key];
    }
  }

  for (const key of Object.keys(grand)) {
    grand[key] = Math.round(grand[key] * 100) / 100;
  }

  // ACC wants the receipt range zeroed on the 95 grand-total row.
  grand.strans = 0;
  grand.etrans = 0;
  grand.previousZCount = 0;
  grand.currentZCount = 0;

  return grand;
}

